-- jazz.sqlite.large-value-trigger-set.v1
CREATE INDEX IF NOT EXISTS "notes__lv_a" ON "notes" (id) WHERE (substr(CAST("a" AS BLOB), 1, 1) = X'FF');
CREATE INDEX IF NOT EXISTS "notes__lv_b" ON "notes" (id) WHERE (substr(CAST("b" AS BLOB), 1, 1) = X'FF');
CREATE TRIGGER IF NOT EXISTS "notes__lv_v1_ins" AFTER INSERT ON "notes" WHEN (substr(CAST(NEW."a" AS BLOB), 1, 1) = X'FF') OR (substr(CAST(NEW."b" AS BLOB), 1, 1) = X'FF') BEGIN INSERT INTO _jazz_lv_root (root, durable) SELECT r, 1 FROM (SELECT (CASE WHEN (substr(CAST(NEW."a" AS BLOB), 1, 1) = X'FF') THEN substr(CAST(NEW."a" AS BLOB), 2, 32) END) AS r) WHERE r IS NOT NULL ON CONFLICT (root) DO UPDATE SET durable = durable + 1; INSERT INTO _jazz_lv_root (root, durable) SELECT r, 1 FROM (SELECT (CASE WHEN (substr(CAST(NEW."b" AS BLOB), 1, 1) = X'FF') THEN substr(CAST(NEW."b" AS BLOB), 2, 32) END) AS r) WHERE r IS NOT NULL ON CONFLICT (root) DO UPDATE SET durable = durable + 1; END;
CREATE TRIGGER IF NOT EXISTS "notes__lv_v1_del" AFTER DELETE ON "notes" WHEN (substr(CAST(OLD."a" AS BLOB), 1, 1) = X'FF') OR (substr(CAST(OLD."b" AS BLOB), 1, 1) = X'FF') BEGIN UPDATE _jazz_lv_root SET durable = durable - 1 WHERE root = (CASE WHEN (substr(CAST(OLD."a" AS BLOB), 1, 1) = X'FF') THEN substr(CAST(OLD."a" AS BLOB), 2, 32) END); UPDATE _jazz_lv_root SET durable = durable - 1 WHERE root = (CASE WHEN (substr(CAST(OLD."b" AS BLOB), 1, 1) = X'FF') THEN substr(CAST(OLD."b" AS BLOB), 2, 32) END); END;
CREATE TRIGGER IF NOT EXISTS "notes__lv_v1_upd" AFTER UPDATE OF "a", "b" ON "notes" WHEN (CASE WHEN (substr(CAST(OLD."a" AS BLOB), 1, 1) = X'FF') THEN substr(CAST(OLD."a" AS BLOB), 2, 32) END) IS NOT (CASE WHEN (substr(CAST(NEW."a" AS BLOB), 1, 1) = X'FF') THEN substr(CAST(NEW."a" AS BLOB), 2, 32) END) OR (CASE WHEN (substr(CAST(OLD."b" AS BLOB), 1, 1) = X'FF') THEN substr(CAST(OLD."b" AS BLOB), 2, 32) END) IS NOT (CASE WHEN (substr(CAST(NEW."b" AS BLOB), 1, 1) = X'FF') THEN substr(CAST(NEW."b" AS BLOB), 2, 32) END) BEGIN UPDATE _jazz_lv_root SET durable = durable - 1 WHERE root = (CASE WHEN (substr(CAST(OLD."a" AS BLOB), 1, 1) = X'FF') THEN substr(CAST(OLD."a" AS BLOB), 2, 32) END) AND (CASE WHEN (substr(CAST(OLD."a" AS BLOB), 1, 1) = X'FF') THEN substr(CAST(OLD."a" AS BLOB), 2, 32) END) IS NOT (CASE WHEN (substr(CAST(NEW."a" AS BLOB), 1, 1) = X'FF') THEN substr(CAST(NEW."a" AS BLOB), 2, 32) END); INSERT INTO _jazz_lv_root (root, durable) SELECT r, 1 FROM (SELECT (CASE WHEN (substr(CAST(NEW."a" AS BLOB), 1, 1) = X'FF') THEN substr(CAST(NEW."a" AS BLOB), 2, 32) END) AS r) WHERE r IS NOT NULL AND r IS NOT (CASE WHEN (substr(CAST(OLD."a" AS BLOB), 1, 1) = X'FF') THEN substr(CAST(OLD."a" AS BLOB), 2, 32) END) ON CONFLICT (root) DO UPDATE SET durable = durable + 1; UPDATE _jazz_lv_root SET durable = durable - 1 WHERE root = (CASE WHEN (substr(CAST(OLD."b" AS BLOB), 1, 1) = X'FF') THEN substr(CAST(OLD."b" AS BLOB), 2, 32) END) AND (CASE WHEN (substr(CAST(OLD."b" AS BLOB), 1, 1) = X'FF') THEN substr(CAST(OLD."b" AS BLOB), 2, 32) END) IS NOT (CASE WHEN (substr(CAST(NEW."b" AS BLOB), 1, 1) = X'FF') THEN substr(CAST(NEW."b" AS BLOB), 2, 32) END); INSERT INTO _jazz_lv_root (root, durable) SELECT r, 1 FROM (SELECT (CASE WHEN (substr(CAST(NEW."b" AS BLOB), 1, 1) = X'FF') THEN substr(CAST(NEW."b" AS BLOB), 2, 32) END) AS r) WHERE r IS NOT NULL AND r IS NOT (CASE WHEN (substr(CAST(OLD."b" AS BLOB), 1, 1) = X'FF') THEN substr(CAST(OLD."b" AS BLOB), 2, 32) END) ON CONFLICT (root) DO UPDATE SET durable = durable + 1; END;
